arguments.script:
var setup=UnityEditor.SceneManagement.EditorSceneManager.GetSceneManagerSetup(); var lines=new System.Collections.Generic.List<string>();
try { foreach(var b in System.IO.Directory.GetFiles("scripts/tilemap-20261110/backup","*.unity")) {
var name=System.IO.Path.GetFileName(b);string temp="Assets/Editor/TilemapVerification.unity";System.IO.File.Copy(b,temp,true);UnityEditor.AssetDatabase.ImportAsset(temp);
var before=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(temp);
string Key(UnityEngine.Sprite sp,UnityEngine.Vector3 pos,UnityEngine.Quaternion rot,UnityEngine.Vector3 scale,UnityEngine.Color color,int layer,int order,UnityEngine.Matrix4x4? actual=null) {return UnityEditor.AssetDatabase.GetAssetPath(sp)+"|"+pos.ToString("F3")+"|"+string.Join(",",Enumerable.Range(0,16).Select(i=>System.Math.Round((actual ?? UnityEngine.Matrix4x4.TRS(UnityEngine.Vector3.zero,rot,scale))[i],3).ToString()))+"|"+color.ToString("F3")+"|"+layer+"|"+order;}
var old=before.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.SpriteRenderer>(true)).Where(r=>r.sprite!=null && r.enabled && r.gameObject.activeInHierarchy && r.drawMode==UnityEngine.SpriteDrawMode.Simple).Where(r=>r.name.StartsWith("GroundTile") || r.GetComponentsInParent<UnityEngine.Transform>(true).Any(t=>t.name=="Terrain")).Where(r=>r.GetComponentInParent<UnityEngine.Rigidbody2D>()==null && r.GetComponentInParent<UnityEngine.Animator>()==null && r.GetComponents<UnityEngine.MonoBehaviour>().Length==0).Select(r=>Key(r.sprite,r.transform.position,r.transform.rotation,UnityEngine.Vector3.Scale(r.transform.lossyScale,new UnityEngine.Vector3(r.flipX?-1:1,r.flipY?-1:1,1)),r.color,r.sortingLayerID,r.sortingOrder)).OrderBy(k=>k).ToArray();
var after=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/"+name);
var keys=new System.Collections.Generic.List<string>();foreach(var m in after.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>(true))) {var rr=m.GetComponent<UnityEngine.Tilemaps.TilemapRenderer>();foreach(var c in m.cellBounds.allPositionsWithin){if(!m.HasTile(c))continue;var mx=m.GetTransformMatrix(c);keys.Add(Key(m.GetSprite(c),m.CellToWorld(c)+new UnityEngine.Vector3(.4f,.4f,0),mx.rotation,mx.lossyScale,m.GetColor(c),rr.sortingLayerID,rr.sortingOrder,mx));}}
if(name.Contains("Cave"))System.IO.File.WriteAllLines("scripts/tilemap-20261110/cave-diff.txt",old.Except(keys).Take(4).Concat(keys.Except(old).Take(4)));lines.Add(name+": tiles="+keys.Count+" source="+old.Length+" transforms/sprites/colors/sorting="+old.SequenceEqual(keys.OrderBy(k=>k)));
} } finally {UnityEditor.SceneManagement.EditorSceneManager.RestoreSceneManagerSetup(setup);UnityEditor.AssetDatabase.DeleteAsset("Assets/Editor/TilemapVerification.unity");}
System.IO.File.WriteAllLines("scripts/tilemap-20261110/verification.txt",lines);return string.Join("\n",lines);
